package com.ezylang.evalex.parser;

import com.ezylang.evalex.config.ExpressionConfiguration;
import com.ezylang.evalex.functions.FunctionIfc;
import com.ezylang.evalex.operators.OperatorIfc;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

import java.util.List;

public class TokenizerTest {

    @Test
    public void parseInputValidTest() {
        ExpressionConfiguration mockConfiguration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("2+2", mockConfiguration);
        List<Token> result = tokenizer.parse();
        Assert.assertNotNull(result);
    }

    @Test(expected = ParseException.class)
    public void parseInputInvalidTest() {
        ExpressionConfiguration mockConfiguration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("2++2", mockConfiguration);
        tokenizer.parse();
    }

    @Test
    public void parseStringLiteralValidTest() {
        ExpressionConfiguration mockConfiguration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("\"test\"", mockConfiguration);
        Token result = tokenizer.parseStringLiteral();
        Assert.assertEquals("test", result.content);
    }

    @Test(expected = ParseException.class)
    public void parseStringLiteralInvalidTest() {
        ExpressionConfiguration mockConfiguration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("test", mockConfiguration);
        tokenizer.parseStringLiteral();
    }

    @Test
    public void tokenParserValidFunctionTest() {
        FunctionIfc mockFunction = Mockito.mock(FunctionIfc.class);
        Mockito.when(mockFunction.getFunctionName()).thenReturn("testFunction");
        ExpressionConfiguration mockConfiguration = Mockito.mock(ExpressionConfiguration.class);
        Mockito.when(mockConfiguration.getFunctionDictionary()).thenReturn(mockFunction);

        Tokenizer tokenizer = new Tokenizer("testFunction", mockConfiguration);
        List<Token> result = tokenizer.parse();
        Assert.assertEquals("testFunction", result.get(0).content);
    }

    @Test
    public void tokenParserValidOperatorTest() {
        OperatorIfc mockOperator = Mockito.mock(OperatorIfc.class);
        Mockito.when(mockOperator.getOperatorName()).thenReturn("+");
        ExpressionConfiguration mockConfiguration = Mockito.mock(ExpressionConfiguration.class);
        Mockito.when(mockConfiguration.getOperatorDictionary()).thenReturn(mockOperator);

        Tokenizer tokenizer = new Tokenizer("2+2", mockConfiguration);
        List<Token> result = tokenizer.parse();
        Assert.assertEquals("+", result.get(1).content);
    }
}
